CREATE SEQUENCE VideoSequence START WITH 1 INCREMENT BY 1;
CREATE TABLE Users(Username NVARCHAR(50) PRIMARY KEY,Password NVARCHAR(100) NOT NULL,Phone NVARCHAR(15),Fullname NVARCHAR(50),Email NVARCHAR(150) UNIQUE NOT NULL,Admin BIT NOT NULL,Active BIT NOT NULL,Images NVARCHAR(500));
CREATE TABLE Category(CategoryId INT IDENTITY PRIMARY KEY,CategoryName NVARCHAR(100),CategoryCode NVARCHAR(100) UNIQUE,Images NVARCHAR(500),Status BIT);
CREATE TABLE Videos(VideoId NVARCHAR(50) PRIMARY KEY,Title NVARCHAR(200),Poster NVARCHAR(500),Views INT DEFAULT 0 CHECK(Views>=0),Description NVARCHAR(500),Active BIT,CategoryId INT REFERENCES Category(CategoryId),Price DECIMAL(18,2) DEFAULT 99000 NOT NULL,Stock INT DEFAULT 25 NOT NULL);
CREATE TABLE Favorites(FavoriteId INT IDENTITY PRIMARY KEY,LikedDate DATE,VideoId NVARCHAR(50) REFERENCES Videos(VideoId),Username NVARCHAR(50) REFERENCES Users(Username),CONSTRAINT UQ_Favorites UNIQUE(Username,VideoId));
CREATE TABLE Shares(ShareId INT IDENTITY PRIMARY KEY,Emails NVARCHAR(50),SharedDate DATE,Username NVARCHAR(50) REFERENCES Users(Username),VideoId NVARCHAR(50) REFERENCES Videos(VideoId));
CREATE TABLE Orders(OrderId BIGINT IDENTITY PRIMARY KEY,Username NVARCHAR(50) REFERENCES Users(Username),RecipientName NVARCHAR(100),Phone NVARCHAR(15),Address NVARCHAR(300),Note NVARCHAR(500),PaymentMethod VARCHAR(10) DEFAULT 'COD',Status VARCHAR(20) DEFAULT 'NEW',TotalAmount DECIMAL(18,2),CreatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UpdatedAt TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE OrderItems(OrderItemId BIGINT IDENTITY PRIMARY KEY,OrderId BIGINT REFERENCES Orders(OrderId),VideoId NVARCHAR(50) REFERENCES Videos(VideoId),Title NVARCHAR(200),Poster NVARCHAR(500),UnitPrice DECIMAL(18,2),Quantity INT CHECK(Quantity BETWEEN 1 AND 20));
CREATE INDEX IX_Favorites_Video ON Favorites(VideoId);
CREATE INDEX IX_Shares_Video ON Shares(VideoId);
CREATE INDEX IX_Videos_Category ON Videos(CategoryId,Active,VideoId);
